/* The review agenda belongs to Exam 2. Self-checks share its scoped event stream. */
(() => {
  'use strict';
  let chapter='all',status='all',query='';
  const labels={covered:'Study material available',partial:'Some detail still needed',pending:'Course material needed'};
  function render(root,esc){
    const review=EXAM2_CONTENT.review,p=Exam2Store.state(),completed=p.completed.filter(id=>review.topics.some(t=>t.id===id)).length;
    root.innerHTML=`<p class="eyebrow">INSTRUCTOR REVIEW SHEET</p><h2>Exam 2 review checklist</h2><p>The review sheet lists Chapters 7 (Emotion and Motivation), 9 (Memory, two lectures), and 8 (Learning, two lectures). Chapter 10 (Language) belongs to Exam 3.</p><p>The sheet’s questions are a sample, rather than a complete exam blueprint. Lecture, videos, readings and textbook material are eligible unless excluded. Section 7-4 motivation material beyond achievement motivation is excluded by the sheet.</p><p class="subtle">The exam-weighting document mentioned in the sheet has not been supplied. Coverage labels below describe the material available on this site. “Ready from memory” is your own recall check.</p><div class="select-row"><label>Chapter<select id="exam2ReviewChapter"><option value="all">All chapters</option><option value="7">7 · Emotion & motivation</option><option value="9">9 · Memory</option><option value="8">8 · Learning</option></select></label><label>Coverage<select id="exam2ReviewStatus"><option value="all">All topics</option>${Object.entries(labels).map(([value,label])=>`<option value="${value}">${esc(label)}</option>`).join('')}</select></label><label>Search review questions<input type="search" id="exam2ReviewSearch" placeholder="Try: interference, conditioning…" value="${esc(query)}"></label></div><p class="subtle" id="exam2ReviewCount" role="status"></p><div id="exam2ReviewTopics" tabindex="0" role="region" aria-label="Filtered exam review prompts"></div><p class="topic-source">Source: ${esc(review.source)} · ${completed} / ${review.topics.length} marked ready from memory.</p>`;
    root.querySelector('#exam2ReviewChapter').value=chapter;root.querySelector('#exam2ReviewStatus').value=status;
    const update=()=>{
      const topics=review.topics.filter(t=>(chapter==='all'||t.chapter===chapter)&&(status==='all'||t.status===status)&&t.prompt.toLowerCase().includes(query.toLowerCase()));
      root.querySelector('#exam2ReviewCount').textContent=topics.length+' matching review prompts';
      root.querySelector('#exam2ReviewTopics').innerHTML=topics.map(t=>`<details class="reference-section exam2-review-item"><summary><span>${esc(t.prompt)}</span><small class="badge ${t.status==='covered'?'':'warn'}">${esc(labels[t.status])}</small></summary><div class="exam2-review-body"><p class="subtle">Chapter ${t.chapter} · ${t.kind==='text'?'Textbook prompt':'Lecture prompt'}</p><p>${esc(t.note)}</p><div class="actions">${t.lessonIds.map(id=>`<button class="btn secondary" data-review-lesson="${id}">${esc(EXAM2_CONTENT.lessons.find(l=>l.id===id).title)}</button>`).join('')}</div><label class="exam2-ready"><input type="checkbox" data-review-ready="${t.id}" ${Exam2Store.state().completed.includes(t.id)?'checked':''}> Ready from memory</label></div></details>`).join('')||'<p>No matching prompts. Try another filter.</p>';
      root.querySelectorAll('[data-review-lesson]').forEach(b=>b.onclick=()=>Exam2Study.openLesson(b.dataset.reviewLesson));
      root.querySelectorAll('[data-review-ready]').forEach(b=>b.onchange=()=>{Exam2Store.record('lesson',b.dataset.reviewReady,{value:b.checked});const n=Exam2Store.state().completed.filter(id=>review.topics.some(t=>t.id===id)).length;root.querySelector('.topic-source').textContent='Source: '+review.source+' · '+n+' / '+review.topics.length+' marked ready from memory.';if(!Exam2Store.storageOK())toast('Export Exam 2 progress to keep a recovery copy.');});
    };
    root.querySelector('#exam2ReviewChapter').onchange=e=>{chapter=e.target.value;update();};root.querySelector('#exam2ReviewStatus').onchange=e=>{status=e.target.value;update();};root.querySelector('#exam2ReviewSearch').oninput=e=>{query=e.target.value;update();};update();
  }
  globalThis.Exam2Review={render};
})();
